  `raw_app_meta_data` JSON,
  `raw_user_meta_data` JSON,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `banned_until` DATETIME(6),
  `deleted_at` DATETIME(6),
  `is_sso_user` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_key` (`email`),
  UNIQUE KEY `users_phone_key` (`phone`),
  KEY `idx_users_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GoTrue auth.users equivalent (see AUTH_MIGRATION.md)';


