  `student_id` CHAR(36) NOT NULL,
  `course_id` CHAR(36) NOT NULL,
  `enrolled_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  `progress_percent` INT DEFAULT 0 NOT NULL COMMENT 'pg_default: 0',
  `last_lesson_id` CHAR(36),
  `enrolled_by` CHAR(36),
  `enrollment_method` TEXT DEFAULT ('activation_code') NOT NULL COMMENT 'pg_default: ''activation_code''',
  `status` VARCHAR(191) DEFAULT 'active' NOT NULL COMMENT 'pg_default: ''active''',
  `activation_method` VARCHAR(64) GENERATED ALWAYS AS (`enrollment_method`) STORED COMMENT 'pg: GENERATED ALWAYS AS (enrollment_method) STORED',
  `hidden_from_instructor` TINYINT(1) DEFAULT 0 NOT NULL COMMENT 'pg_default: false',
  `visibility_level` PUBLIC.ENROLLMENT_VISIBILITY DEFAULT 'all' NOT NULL COMMENT 'UNCONVERTED PG type: public.enrollment_visibility; pg_default: ''all''',
  `assigned_price` DECIMAL(20,6),
  PRIMARY KEY (`id`),
  UNIQUE (`student_id`, `course_id`),
  CONSTRAINT `fk_enrollments_student_id` FOREIGN KEY (`student_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_enrollments_course_id` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_enrollments_last_lesson_id` FOREIGN KEY (`last_lesson_id`) REFERENCES `lessons` (`id`),
  CONSTRAINT `fk_enrollments_enrolled_by` FOREIGN KEY (`enrolled_by`) REFERENCES `profiles` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_enrollments_c0` CHECK ((progress_percent IS NULL OR (progress_percent >= 0 AND progress_percent <= 100)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ===========================================================================
-- TABLE: lesson_progress
-- ===========================================================================
CREATE TABLE IF NOT EXISTS `lesson_progress` (
  `id` CHAR(36) DEFAULT (UUID()) COMMENT 'pg_default: gen_random_uuid()',
  `student_id` CHAR(36) NOT NULL,
  `lesson_id` CHAR(36) NOT NULL,
  `course_id` CHAR(36) NOT NULL,
  `watch_position_seconds` INT DEFAULT 0 NOT NULL COMMENT 'pg_default: 0',
  `completed` TINYINT(1) DEFAULT 0 NOT NULL COMMENT 'pg_default: false',
  `last_watched_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  PRIMARY KEY (`id`),
  UNIQUE (`student_id`, `lesson_id`),
  CONSTRAINT `fk_lesson_progress_student_id` FOREIGN KEY (`student_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_lesson_progress_lesson_id` FOREIGN KEY (`lesson_id`) REFERENCES `lessons` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_lesson_progress_course_id` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_lesson_progress_c0` CHECK ((watch_position_seconds IS NULL OR watch_position_seconds >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ===========================================================================
-- TABLE: credits
-- ===========================================================================
CREATE TABLE IF NOT EXISTS `credits` (
  `id` CHAR(36) DEFAULT (UUID()) COMMENT 'pg_default: gen_random_uuid()',
  `doctor_id` CHAR(36) NOT NULL UNIQUE,
  `allocated` INT DEFAULT 0 NOT NULL COMMENT 'pg_default: 0',
  `consumed` INT DEFAULT 0 NOT NULL COMMENT 'pg_default: 0',
  `remaining` INT DEFAULT 0 NOT NULL COMMENT 'pg_default: 0',
  `updated_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_credits_doctor_id` FOREIGN KEY (`doctor_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_credits_c0` CHECK ((remaining >= 0)),
  CONSTRAINT `chk_credits_c1` CHECK ((consumed >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ===========================================================================
-- TABLE: audit_logs
-- ===========================================================================
CREATE TABLE IF NOT EXISTS `audit_logs` (
