-- ===========================================================================
-- TABLE: upload_audit_logs
-- ===========================================================================
CREATE TABLE IF NOT EXISTS `upload_audit_logs` (
  `id` CHAR(36) DEFAULT (UUID()) COMMENT 'pg_default: gen_random_uuid()',
  `upload_id` CHAR(36) NOT NULL,
  `actor_id` CHAR(36) NOT NULL COMMENT 'PG default not portable: auth.uid(); pg_default: auth.uid()',
  `event` TEXT NOT NULL,
  `details` JSON,
  `created_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_upload_audit_logs_upload_id` FOREIGN KEY (`upload_id`) REFERENCES `video_uploads` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_upload_audit_logs_actor_id` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `chk_upload_audit_logs_c0` CHECK (( event IN ( 'upload_started','upload_completed','upload_failed', 'upload_paused','upload_resumed','upload_canceled', 'video_deleted','video_replaced','video_reprocessed', 'processing_started','encoding_started','ready', 'verification_started','verification_passed','verification_failed', 'thumbnail_generated','thumbnail_replaced', 'recovery_detected','recovery_started','recovery_completed' ) )),
  CONSTRAINT `chk_upload_audit_logs_c1` CHECK (( event IN ( 'upload_started','upload_completed','upload_failed', 'upload_paused','upload_resumed','upload_canceled', 'video_deleted','video_replaced','video_reprocessed', 'processing_started','encoding_started','ready', 'verification_started','verification_passed','verification_failed', 'thumbnail_generated','thumbnail_replaced', 'recovery_detected','recovery_started','recovery_completed', 'chunk_upload_started','chunk_received','assembly_triggered', 'assembly_started','assembly_completed','assembly_failed', 'retry_upload','retry_processing','lock_recovery_recovering', 'lock_recovery_failed','vdocipher_init_started','vdocipher_init_completed', 'vdocipher_s3_upload_started','vdocipher_s3_upload_completed', 'vdocipher_encoding_complete','vdocipher_encoding_failed', 'vdocipher_polling_started','upload_resumed' ) ))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
