  `violation_limit` INT DEFAULT 3 NOT NULL COMMENT 'pg_default: 3',
  `warning_message` TEXT DEFAULT ('Screenshots of protected educational content are prohibited. Repeated violations may result in temporary account suspension.') NOT NULL COMMENT 'pg_default: ''Screenshots of protected educational content are prohibited. Repeated violations may result in temporary account suspension.''',
  `auto_logout` TINYINT(1) DEFAULT 1 NOT NULL COMMENT 'pg_default: true',
  `auto_suspend` TINYINT(1) DEFAULT 1 NOT NULL COMMENT 'pg_default: true',
  `suspension_hours` INT DEFAULT 24 NOT NULL COMMENT 'pg_default: 24',
  `strike1_action` VARCHAR(16) DEFAULT 'warning' NOT NULL COMMENT 'pg_default: ''warning''',
  `strike2_action` VARCHAR(16) DEFAULT 'logout' NOT NULL COMMENT 'pg_default: ''logout''',
  `strike3_action` VARCHAR(16) DEFAULT 'suspend' NOT NULL COMMENT 'pg_default: ''suspend''',
  `updated_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  `updated_by` CHAR(36),
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_content_protection_policies_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `profiles` (`id`)
