  `reset_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  `earnings_before` DECIMAL(20,6) DEFAULT 0 NOT NULL COMMENT 'pg_default: 0',
