-- ===========================================================================
-- TABLE: doctor_earnings_events
-- ===========================================================================
CREATE TABLE IF NOT EXISTS `doctor_earnings_events` (
  `id` CHAR(36) DEFAULT (UUID()) COMMENT 'pg_default: gen_random_uuid()',
  `doctor_id` CHAR(36) NOT NULL,
  `course_id` CHAR(36),
  `student_id` CHAR(36),
  `event_type` TEXT NOT NULL,
  `pricing_mode` TEXT NOT NULL,
  `price_snapshot` DECIMAL(12,2) DEFAULT 0 NOT NULL COMMENT 'pg_default: 0',
  `earnings_amount` DECIMAL(12,2) DEFAULT 0 NOT NULL COMMENT 'pg_default: 0',
  `notes` TEXT,
  `created_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  `transaction_type` TEXT DEFAULT ('purchase') NOT NULL COMMENT 'pg_default: ''purchase''',
  `student_name_snapshot` TEXT,
  `course_name_snapshot` TEXT,
  `student_email_snapshot` TEXT,
  `student_phone_snapshot` TEXT,
  `student_watermark_snapshot` TEXT,
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_doctor_earnings_events_doctor_id` FOREIGN KEY (`doctor_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_doctor_earnings_events_course_id` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_doctor_earnings_events_student_id` FOREIGN KEY (`student_id`) REFERENCES `profiles` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_doctor_earnings_events_c0` CHECK ((pricing_mode IN ('platform', 'credit', 'course', 'doctor_independent'))),
  CONSTRAINT `chk_doctor_earnings_events_c1` CHECK ((transaction_type IN ('purchase', 'removal', 'suspension_refund', 'adjustment', 'account_deletion')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ===========================================================================
-- TABLE: doctor_pricing_history
-- ===========================================================================
CREATE TABLE IF NOT EXISTS `doctor_pricing_history` (
  `id` CHAR(36) DEFAULT (UUID()) COMMENT 'pg_default: gen_random_uuid()',
  `doctor_id` CHAR(36) NOT NULL,
  `changed_by` CHAR(36) NOT NULL,
  `field_name` TEXT NOT NULL,
  `old_value` TEXT,
  `new_value` TEXT,
  `created_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_doctor_pricing_history_doctor_id` FOREIGN KEY (`doctor_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_doctor_pricing_history_changed_by` FOREIGN KEY (`changed_by`) REFERENCES `profiles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ===========================================================================
-- TABLE: doctor_earnings_transactions
-- ===========================================================================
CREATE TABLE IF NOT EXISTS `doctor_earnings_transactions` (
  `id` CHAR(36) DEFAULT (UUID()) COMMENT 'pg_default: gen_random_uuid()',
  `doctor_id` CHAR(36) NOT NULL,
  `course_id` CHAR(36),
  `student_id` CHAR(36),
  `amount_egp` DECIMAL(12,2) DEFAULT 0 NOT NULL COMMENT 'pg_default: 0',
  `transaction_type` TEXT DEFAULT ('enrollment') NOT NULL COMMENT 'pg_default: ''enrollment''',
  `description` TEXT,
  `created_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_doctor_earnings_transactions_doctor_id` FOREIGN KEY (`doctor_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_doctor_earnings_transactions_course_id` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_doctor_earnings_transactions_student_id` FOREIGN KEY (`student_id`) REFERENCES `profiles` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ===========================================================================
-- TABLE: doctor_payout_requests
-- ===========================================================================
CREATE TABLE IF NOT EXISTS `doctor_payout_requests` (
  `id` CHAR(36) DEFAULT (UUID()) COMMENT 'pg_default: gen_random_uuid()',
