  `amount_egp` DECIMAL(12,2) NOT NULL,
  `status` TEXT DEFAULT ('pending') NOT NULL COMMENT 'pg_default: ''pending''',
  `method` TEXT,
  `notes` TEXT,
  `created_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  `updated_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_doctor_payout_requests_doctor_id` FOREIGN KEY (`doctor_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE
