CREATE TABLE IF NOT EXISTS `play_integrity_nonces` (
  `id` CHAR(36) DEFAULT (UUID()) COMMENT 'pg_default: gen_random_uuid()',
  `nonce` VARCHAR(191) NOT NULL UNIQUE,
  `user_id` CHAR(36),
