) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ===========================================================================
-- TABLE: security_config
-- ===========================================================================
CREATE TABLE IF NOT EXISTS `security_config` (
  `id` CHAR(36) DEFAULT (UUID()) COMMENT 'pg_default: gen_random_uuid()',
  `play_integrity_enabled` TINYINT(1) DEFAULT 0 NOT NULL COMMENT 'pg_default: false',
  `expected_cert_sha256` TEXT,
  `minimum_app_version` TEXT DEFAULT ('1.0.0') NOT NULL COMMENT 'pg_default: ''1.0.0''',
  `force_update` TINYINT(1) DEFAULT 0 NOT NULL COMMENT 'pg_default: false',
  `security_version` INT DEFAULT 1 NOT NULL COMMENT 'pg_default: 1',
  `extras` JSON DEFAULT ('{}') NOT NULL COMMENT 'pg_default: ''{}''',
  `is_active` TINYINT(1) DEFAULT 1 NOT NULL COMMENT 'pg_default: true',
  `updated_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  `updated_by` CHAR(36),
  `created_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP NOT NULL COMMENT 'pg_default: now()',
  `expected_cert_sha256s` JSON DEFAULT ('[]') NOT NULL COMMENT 'pg_default: ''[]''',
  `minimum_supported_version` TEXT DEFAULT ('1.0.0') NOT NULL COMMENT 'pg_default: ''1.0.0''',
  `latest_version` TEXT DEFAULT ('1.0.0') NOT NULL COMMENT 'pg_default: ''1.0.0''',
  `update_title` TEXT DEFAULT ('Update Required') NOT NULL COMMENT 'pg_default: ''Update Required''',
  `update_message` TEXT DEFAULT ('A critical update is available. Please update the app to continue.') NOT NULL COMMENT 'pg_default: ''A critical update is available. Please update the app to continue.''',
  `android_store_url` TEXT DEFAULT ('') NOT NULL COMMENT 'pg_default: ''''',
  `ios_store_url` TEXT DEFAULT ('') NOT NULL COMMENT 'pg_default: ''''',
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_security_config_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
